nodes.script:
const total = {{nodes.summary-total.output}}[0];
const byCategory = {{nodes.summary-by-category.output}};
const items = [
  { label: "总支出", value: "¥" + total.total },
  { label: "笔数", value: total.cnt, hint: "平均 ¥" + (total.avg_amount === null ? 0 : total.avg_amount) },
];
for (const c of byCategory.slice(0, 3)) {
  items.push({ label: c.category, value: "¥" + c.total, hint: c.cnt + " 笔" });
}
console.log(JSON.stringify({ title: "月度汇总", items }));
